class Solution:
    def differenceOfDistinctValues(self, grid: list[list[int]]) -> list[list[int]]:
        m, n = len(grid), len(grid[0])
        ans = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                top_left = set()
                cr, cc = r - 1, c - 1
                while cr >= 0 and cc >= 0:
                    top_left.add(grid[cr][cc])
                    cr -= 1
                    cc -= 1
                bottom_right = set()
                cr, cc = r + 1, c + 1
                while cr < m and cc < n:
                    bottom_right.add(grid[cr][cc])
                    cr += 1
                    cc += 1
                ans[r][c] = abs(len(top_left) - len(bottom_right))
        return ans

class Solution {
public:
    vector<vector<int>> differenceOfDistinctValues(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> ans(m, vector<int>(n, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                unordered_set<int> tl, br;
                for (int i = r - 1, j = c - 1; i >= 0 && j >= 0; --i, --j) {
                    tl.insert(grid[i][j]);
                }
                for (int i = r + 1, j = c + 1; i < m && j < n; ++i, ++j) {
                    br.insert(grid[i][j]);
                }
                ans[r][c] = abs((int)tl.size() - (int)br.size());
            }
        }
        return ans;
    }
};

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int[][] differenceOfDistinctValues(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] ans = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                Set<Integer> tl = new HashSet<>();
                Set<Integer> br = new HashSet<>();
                for (int i = r - 1, j = c - 1; i >= 0 && j >= 0; i--, j--) {
                    tl.add(grid[i][j]);
                }
                for (int i = r + 1, j = c + 1; i < m && j < n; i++, j++) {
                    br.add(grid[i][j]);
                }
                ans[r][c] = Math.abs(tl.size() - br.size());
            }
        }
        return ans;
    }
}

